import React, { useCallback, useEffect, useMemo, useState } from "react"

import Shell from "../components/layout/Shell"
import Panel from "../components/layout/Panel"
import Breadcrumb from "../components/ui/Breadcrumb"
import TickerMark from "../components/ui/TickerMark"
import Delta from "../components/ui/Delta"
import Badge from "../components/ui/Badge"
import Icon from "../components/ui/Icon"
import Select from "../components/ui/Select"
import Toggle from "../components/ui/Toggle"
import DeltaChart from "../components/delta/DeltaChart"

import { COMPANIES, getCompany, ANCHOR_DATE } from "../data/companies"
import { getDelta, getDeltaBounds, DELTA_INTERVALS } from "../data/delta"
import { generateCandles } from "../data/candles"
import { getSessionChange } from "../data/markets"

/* -------------------------------------------------------------------------- */
/* Formatting                                                                  */
/* -------------------------------------------------------------------------- */

const DASH = "—"
const isNum = v => v !== null && v !== undefined && Number.isFinite(v)

function compact(value) {
  if (!isNum(value)) return DASH
  const abs = Math.abs(value)
  const sign = value < 0 ? "−" : ""
  if (abs >= 1e9) return sign + (abs / 1e9).toFixed(2) + "B"
  if (abs >= 1e6) return sign + (abs / 1e6).toFixed(2) + "M"
  if (abs >= 1e3) return sign + (abs / 1e3).toFixed(1) + "K"
  return sign + abs.toFixed(0)
}

const usd = (v, d = 2) =>
  isNum(v) ? (v < 0 ? "−$" : "$") + Math.abs(v).toFixed(d) : DASH

/** The dataset is anchored to a fixed Eastern session, so the offset is constant. */
const ET_OFFSET_HOURS = -4

function clockTime(timestamp) {
  if (!isNum(timestamp)) return DASH
  const d = new Date((timestamp + ET_OFFSET_HOURS * 3600) * 1000)
  let hours = d.getUTCHours()
  const minutes = String(d.getUTCMinutes()).padStart(2, "0")
  const suffix = hours >= 12 ? "PM" : "AM"
  hours = hours % 12 || 12
  return `${hours}:${minutes} ${suffix}`
}

function dayLabel(timestamp) {
  if (!isNum(timestamp)) return DASH
  const d = new Date(timestamp * 1000)
  return d.toISOString().slice(0, 10)
}

/* -------------------------------------------------------------------------- */
/* Configuration                                                               */
/* -------------------------------------------------------------------------- */

const INTERVAL_TABS = [
  { label: "1 minute", value: "1m" },
  { label: "5 minutes", value: "5m" },
  { label: "15 minutes", value: "15m" },
  { label: "1 hour", value: "1h" },
  { label: "Daily", value: "daily" },
]

const INTERVAL_TITLES = {
  "1m": "1 minute",
  "5m": "5 minutes",
  "15m": "15 minutes",
  "1h": "1 hour",
  daily: "Daily",
}

/**
 * Where the "after" snapshot is taken from, expressed as bars back from the live
 * edge. The intraday series is one bar per minute, so the minute labels are
 * literal there; on the daily series they clamp to the earliest comparable bar,
 * which the caption states rather than hiding.
 */
const COMPARE_OPTIONS = [
  { label: "Live (now)", value: "live", barsBack: 0 },
  { label: "5 min ago", value: "back5", barsBack: 5 },
  { label: "15 min ago", value: "back15", barsBack: 15 },
  { label: "Market open", value: "open", barsBack: Number.MAX_SAFE_INTEGER },
]

const ROW_ICONS = {
  price: "trendingUp",
  volume: "barChart",
  rvol: "activity",
  atr: "gauge",
  momentum: "zap",
  newsCount: "newspaper",
  rsi: "gauge",
  macd: "activity",
  vwap: "barChart",
}

const ROW_LABELS = {
  price: "Price",
  volume: "Volume",
  rvol: "Relative volume (RVOL)",
  atr: "Volatility (ATR)",
  momentum: "Momentum",
  newsCount: "News count",
  rsi: "RSI",
  macd: "MACD",
  vwap: "VWAP",
}

const REFRESH_MS = 5000

/**
 * Format one delta cell according to what the metric actually is.
 *
 * Negatives use a true minus (U+2212), never a hyphen, so a column of figures
 * stays aligned and matches the signed Delta column beside it.
 */
function signed(value, digits, suffix = "") {
  return (value < 0 ? "−" : "") + Math.abs(value).toFixed(digits) + suffix
}

function formatValue(row, value) {
  if (!isNum(value)) return DASH
  switch (row.key) {
    case "price":
    case "vwap":
      return usd(value, 2)
    case "atr":
      // ATR moves in thousandths on a one-minute bar; three decimals would
      // round every real change to "0.000".
      return usd(value, 4)
    case "volume":
      return compact(value)
    case "rvol":
      return signed(value, 2, "x")
    case "momentum":
      return signed(value, 2, "%")
    case "newsCount":
      return String(Math.round(value))
    case "rsi":
      return signed(value, 1)
    case "macd":
      return signed(value, 4)
    default:
      return signed(value, 2)
  }
}

/**
 * Which metrics moved enough to be worth calling out. Every chip is generated
 * from a threshold test on real delta values — nothing here is hardcoded, and
 * when nothing clears its threshold the panel says so instead of inventing
 * excitement.
 */
function significantChips(rows) {
  const by = key => rows.find(r => r.key === key)
  const chips = []

  const price = by("price")
  if (price && isNum(price.deltaPct) && Math.abs(price.deltaPct) >= 0.5) {
    chips.push({ key: "price", label: "Price", value: price.deltaPct, kind: "pct" })
  }

  const volume = by("volume")
  if (volume && isNum(volume.deltaPct) && volume.deltaPct >= 50) {
    chips.push({ key: "volume", label: "Volume", value: volume.deltaPct, kind: "pct" })
  }

  const rvol = by("rvol")
  if (rvol && isNum(rvol.after) && rvol.after >= 2) {
    chips.push({ key: "rvol", label: "RVOL", value: rvol.after, kind: "x" })
  }

  const rsi = by("rsi")
  if (rsi && isNum(rsi.after) && (rsi.after >= 70 || rsi.after <= 30)) {
    chips.push({
      key: "rsi",
      label: rsi.after >= 70 ? "RSI overbought" : "RSI oversold",
      value: rsi.after,
      kind: "plain",
    })
  }

  const news = by("newsCount")
  if (news && isNum(news.after) && news.after > 0) {
    chips.push({ key: "news", label: "News detected", value: null, kind: "flag" })
  }

  return chips
}

/* -------------------------------------------------------------------------- */

export default function DeltaPage({ location }) {
  const [symbol, setSymbol] = useState("ACHR")
  const [interval, setIntervalKey] = useState("1m")
  /*
   * Defaults to "15 min ago" rather than "Live (now)" on purpose: auto-refresh
   * walks the cursor FORWARD toward the live edge, so starting at the edge would
   * leave it with nowhere to go and the toggle would look broken. Starting
   * fifteen bars back gives it a real run, and the header badge flips to "Live"
   * when it arrives.
   */
  const [compare, setCompare] = useState("back15")
  const [autoRefresh, setAutoRefresh] = useState(true)

  const bounds = useMemo(() => getDeltaBounds(symbol, interval), [symbol, interval])

  /*
   * The starting bar is DERIVED during render rather than assigned in an effect.
   * An effect would run only in the browser, so the server would render the live
   * edge and the client would immediately jump fifteen bars back — a visible
   * flash of the wrong numbers on every load. Deriving it means the server and
   * the browser agree on the first paint.
   */
  const base = useMemo(() => {
    const option = COMPARE_OPTIONS.find(o => o.value === compare) || COMPARE_OPTIONS[0]
    const target =
      option.barsBack === Number.MAX_SAFE_INTEGER
        ? bounds.minCursor
        : bounds.maxCursor - option.barsBack
    return Math.max(bounds.minCursor, Math.min(bounds.maxCursor, target))
  }, [compare, bounds.minCursor, bounds.maxCursor])

  // How far auto-refresh has walked forward from `base`.
  const [advance, setAdvance] = useState(0)

  // Any change of series or comparison point restarts the walk.
  useEffect(() => {
    setAdvance(0)
  }, [symbol, interval, compare])

  const cursor = Math.min(bounds.maxCursor, base + advance)

  /*
   * Auto-refresh walks the cursor one bar forward every five seconds. Each tick
   * reads the NEXT real candle out of the same deterministic series, so the
   * numbers drift the way a live tape does instead of jumping randomly. At the
   * live edge it simply stops advancing — there is nothing after "now".
   */
  useEffect(() => {
    if (!autoRefresh) return undefined
    const id = window.setInterval(() => {
      setAdvance(current => (base + current >= bounds.maxCursor ? current : current + 1))
    }, REFRESH_MS)
    return () => window.clearInterval(id)
  }, [autoRefresh, base, bounds.maxCursor])

  const data = useMemo(
    () => getDelta(symbol, interval, { cursor }),
    [symbol, interval, cursor]
  )

  const company = getCompany(symbol)
  const change = useMemo(() => getSessionChange(symbol), [symbol])

  // The chart shows the window around the cursor, so the marked bar is the one
  // the table is reading.
  const candles = useMemo(() => {
    const all = generateCandles(symbol, interval === "daily" ? "1M" : "1D")
    if (!all.length || data.cursor === null) return all
    const end = Math.min(all.length, data.cursor + 1)
    const start = Math.max(0, end - (interval === "daily" ? 21 : 90))
    return all.slice(start, end)
  }, [symbol, interval, data.cursor])

  const chips = useMemo(() => significantChips(data.rows), [data.rows])
  const options = COMPANIES.map(c => ({ label: `${c.symbol} — ${c.name}`, value: c.symbol }))

  const beforeLabel =
    interval === "daily" ? dayLabel(data.beforeTime) : clockTime(data.beforeTime)
  const afterLabel =
    interval === "daily" ? dayLabel(data.afterTime) : clockTime(data.afterTime)

  const handleReset = useCallback(
    () => setAdvance(bounds.maxCursor - base),
    [bounds.maxCursor, base]
  )

  return (
    <Shell location={location}>
      <div className="page">
        <div className="page__breadcrumb">
          <Breadcrumb items={[{ label: "Home", to: "/" }, { label: "Delta analysis" }]} />
        </div>

        {/* ---------- Title + explainer note ---------- */}
        <header className="page__head">
          <div className="page__heading">
            <h1 className="page__title">Delta analysis</h1>
            <p className="page__lede">See what&rsquo;s changing, right now.</p>
          </div>
          <aside className="dnote">
            <Icon name="activity" size={16} className="dnote__icon" />
            <div className="dnote__text">
              <p className="dnote__line">
                Delta is the change in a metric between two points in time.
              </p>
              <p className="dnote__line dnote__line--muted">
                It surfaces unusual activity while it&rsquo;s happening, not after the move.
              </p>
            </div>
          </aside>
        </header>

        {/* ---------- Controls ---------- */}
        <section className="dctl">
          <div className="dctl__top">
            <div className="dctl__search">
              <Select
                label="Symbol"
                options={options}
                value={symbol}
                onChange={setSymbol}
              />
            </div>

            <div className="dctl__company">
              <TickerMark symbol={symbol} size={40} />
              <div className="dctl__identity">
                <span className="dctl__symbol">{symbol}</span>
                <span className="dctl__name">{company.name}</span>
                <span className="dctl__chips">
                  <span className="dctl__chip">{company.exchange}</span>
                  <span className="dctl__chip">{company.sector}</span>
                </span>
              </div>
            </div>

            <div className="dctl__quote">
              <span className="dctl__price">{usd(company.price)}</span>
              <Delta value={change.changePct} percent digits={2} />
            </div>

            <button type="button" className="btn btn--primary dctl__watch">
              <Icon name="plus" size={15} className="btn__icon" />
              Add to watchlist
            </button>
          </div>

          <div className="dctl__bottom">
            <div className="dctl__tabs" role="tablist" aria-label="Delta interval">
              {INTERVAL_TABS.map(t => (
                <button
                  key={t.value}
                  type="button"
                  role="tab"
                  aria-selected={interval === t.value}
                  tabIndex={interval === t.value ? 0 : -1}
                  className={
                    "dctl__tab" + (interval === t.value ? " dctl__tab--active" : "")
                  }
                  onClick={() => setIntervalKey(t.value)}
                >
                  {t.label}
                </button>
              ))}
            </div>

            <div className="dctl__right">
              <div className="dctl__compare">
                <Select
                  label="Compare time"
                  options={COMPARE_OPTIONS.map(o => ({ label: o.label, value: o.value }))}
                  value={compare}
                  onChange={setCompare}
                />
              </div>

              <div className="dctl__refresh">
                <span
                  className={
                    "dctl__dot" + (autoRefresh ? " dctl__dot--live" : "")
                  }
                  aria-hidden="true"
                />
                <Toggle
                  label={autoRefresh ? "Auto-refresh on" : "Auto-refresh off"}
                  checked={autoRefresh}
                  onChange={e => setAutoRefresh(e.target.checked)}
                />
              </div>
            </div>
          </div>
        </section>

        {/* ---------- Breakdown + right column ---------- */}
        <div className="dgrid">
          <Panel
            title={`Delta breakdown (${INTERVAL_TITLES[interval]})`}
            subtitle={`Comparing ${beforeLabel} to ${afterLabel}`}
            flush
            actions={
              data.isLive ? (
                <Badge value="Live" tone="bullish" />
              ) : (
                <button type="button" className="btn btn--ghost btn--sm" onClick={handleReset}>
                  Jump to live
                </button>
              )
            }
          >
            <div className="dtable__wrap">
              <table className="dtable">
                <thead>
                  <tr>
                    <th className="dtable__head">Metric</th>
                    <th className="dtable__head dtable__head--num">{beforeLabel}</th>
                    <th className="dtable__head dtable__head--num">{afterLabel}</th>
                    <th className="dtable__head dtable__head--num">Delta</th>
                    <th className="dtable__head dtable__head--num">Change</th>
                  </tr>
                </thead>
                <tbody>
                  {data.rows.map(row => (
                    <tr className="dtable__row" key={row.key}>
                      <td className="dtable__cell">
                        <span className="dtable__metric">
                          <Icon
                            name={ROW_ICONS[row.key] || "activity"}
                            size={16}
                            className="dtable__icon"
                          />
                          {ROW_LABELS[row.key] || row.label}
                        </span>
                      </td>
                      <td className="dtable__cell dtable__cell--num">
                        {formatValue(row, row.before)}
                      </td>
                      <td className="dtable__cell dtable__cell--num">
                        {formatValue(row, row.after)}
                      </td>
                      <td className="dtable__cell dtable__cell--num">
                        <span className={"dtable__delta dtable__delta--" + row.direction}>
                          {isNum(row.delta)
                            ? (row.delta > 0 ? "+" : row.delta < 0 ? "−" : "") +
                              formatValue(row, Math.abs(row.delta))
                            : DASH}
                        </span>
                      </td>
                      <td className="dtable__cell dtable__cell--num">
                        {isNum(row.deltaPct) ? (
                          <Badge
                            tone={
                              row.direction === "up"
                                ? "bullish"
                                : row.direction === "down"
                                ? "bearish"
                                : "neutral"
                            }
                            value={
                              (row.deltaPct > 0 ? "+" : row.deltaPct < 0 ? "−" : "") +
                              Math.abs(row.deltaPct).toFixed(1) +
                              "%"
                            }
                          />
                        ) : isNum(row.delta) && row.delta !== 0 ? (
                          /* The metric moved, but the base was zero so a
                             percentage is undefined — say that rather than
                             printing "No change" over a real move. */
                          <Badge
                            tone={row.direction === "up" ? "bullish" : "bearish"}
                            value="From zero"
                          />
                        ) : (
                          <Badge tone="neutral" value="No change" />
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </Panel>

          <div className="dside">
            <Panel
              title={`Price and volume (${INTERVAL_TITLES[interval]})`}
              subtitle={data.isLive ? "Live edge" : `Marked at ${afterLabel}`}
              flush
            >
              <DeltaChart
                candles={candles}
                height={200}
                markerTime={data.afterTime}
              />
            </Panel>

            {chips.length > 0 ? (
              <section className="dsig">
                <div className="dsig__head">
                  <Icon name="zap" size={15} className="dsig__icon" />
                  <h2 className="dsig__title">Significant activity detected</h2>
                </div>
                <p className="dsig__text">
                  {chips.length} metric{chips.length === 1 ? "" : "s"} moved beyond their normal
                  range between {beforeLabel} and {afterLabel}.
                </p>
                <div className="dsig__chips">
                  {chips.map(chip => (
                    <span className="dsig__chip" key={chip.key}>
                      {chip.kind === "pct" &&
                        `${chip.label} ${chip.value > 0 ? "+" : "−"}${Math.abs(
                          chip.value
                        ).toFixed(1)}%`}
                      {chip.kind === "x" && `${chip.label} ${chip.value.toFixed(1)}x`}
                      {chip.kind === "plain" && `${chip.label} ${chip.value.toFixed(0)}`}
                      {chip.kind === "flag" && chip.label}
                    </span>
                  ))}
                </div>
              </section>
            ) : (
              <section className="dsig dsig--quiet">
                <div className="dsig__head">
                  <Icon name="activity" size={15} className="dsig__icon" />
                  <h2 className="dsig__title">No unusual activity in this interval.</h2>
                </div>
                <p className="dsig__text">
                  Every metric moved within its normal range between {beforeLabel} and{" "}
                  {afterLabel}.
                </p>
              </section>
            )}

            <section className="dexplain">
              <h2 className="dexplain__title">What is delta?</h2>
              <p className="dexplain__text">
                Delta compares a metric at two moments and reports the difference. A large
                volume delta with a small price delta says participation is building before
                the move; a large price delta on flat volume says the opposite.
              </p>
              <p className="dexplain__text">
                Every figure on this screen is read from the same {data.source} series the
                chart draws, sampled at {beforeLabel} and {afterLabel}.
              </p>
            </section>
          </div>
        </div>
      </div>
    </Shell>
  )
}

export const Head = () => <title>Delta analysis · MarketScan</title>
