import React, { useEffect, useRef } from "react"

/**
 * The compact price-and-volume chart on /delta.
 *
 * GATSBY CONSTRAINT: lightweight-charts reads `window` at import time and Gatsby
 * renders every page to HTML in Node at build. So the library is loaded with a
 * dynamic `await import()` INSIDE useEffect, which only ever runs in the browser.
 * Same guard as every other chart in this codebase — there is no exception for
 * small ones.
 *
 * Volume sits on an OVERLAY price scale pinned to the bottom of the same pane
 * rather than in a second chart. At 200px total there is no room for two panes
 * plus an axis, and the overlay is the arrangement trading terminals use for a
 * thumbnail.
 */

function readToken(styles, name) {
  const value = styles.getPropertyValue(name)
  return value && value.trim() ? value.trim() : undefined
}

/** Drops undefined keys so lightweight-charts falls back to its own defaults. */
function defined(object) {
  const out = {}
  for (const key of Object.keys(object)) {
    if (object[key] !== undefined) out[key] = object[key]
  }
  return out
}

export default function DeltaChart({ candles = [], height = 200, markerTime = null }) {
  const containerRef = useRef(null)

  useEffect(() => {
    let chart = null
    let observer = null
    let cancelled = false

    async function mount() {
      const container = containerRef.current
      if (!container || !candles.length) return

      const { createChart, LineStyle } = await import("lightweight-charts")
      if (cancelled || !containerRef.current) return

      const styles = window.getComputedStyle(document.documentElement)

      chart = createChart(container, {
        width: container.clientWidth,
        height,
        layout: {
          background: defined({ color: readToken(styles, "--surface") }),
          ...defined({
            textColor: readToken(styles, "--chart-axis"),
            fontFamily: readToken(styles, "--font-ui"),
          }),
          fontSize: 10,
          attributionLogo: false,
        },
        grid: {
          vertLines: { visible: false },
          horzLines: {
            ...defined({ color: readToken(styles, "--chart-grid") }),
            style: LineStyle.Solid,
          },
        },
        rightPriceScale: { borderVisible: false, scaleMargins: { top: 0.12, bottom: 0.3 } },
        timeScale: { borderVisible: false, timeVisible: true, secondsVisible: false },
        crosshair: {
          vertLine: {
            ...defined({ color: readToken(styles, "--chart-crosshair") }),
            width: 1,
            style: LineStyle.Dashed,
          },
          horzLine: {
            ...defined({ color: readToken(styles, "--chart-crosshair") }),
            width: 1,
            style: LineStyle.Dashed,
          },
        },
        handleScale: false,
        handleScroll: false,
      })

      const area = chart.addAreaSeries({
        ...defined({
          lineColor: readToken(styles, "--chart-up"),
          topColor: readToken(styles, "--chart-delta-top"),
          bottomColor: readToken(styles, "--chart-delta-bottom"),
        }),
        lineWidth: 2,
        priceLineVisible: false,
      })
      area.setData(candles.map(c => ({ time: c.time, value: c.close })))

      const volume = chart.addHistogramSeries({
        priceFormat: { type: "volume" },
        priceScaleId: "volume",
        priceLineVisible: false,
        lastValueVisible: false,
      })
      chart.priceScale("volume").applyOptions({
        scaleMargins: { top: 0.78, bottom: 0 },
        borderVisible: false,
      })
      const volUp = readToken(styles, "--chart-vol-up")
      const volDown = readToken(styles, "--chart-vol-down")
      volume.setData(
        candles.map(c => ({
          time: c.time,
          value: c.volume,
          ...defined({ color: c.close >= c.open ? volUp : volDown }),
        }))
      )

      // Marks the exact bar the delta table is currently reading, so the numbers
      // and the chart are visibly the same moment.
      if (markerTime !== null) {
        area.setMarkers([
          {
            time: markerTime,
            position: "aboveBar",
            shape: "arrowDown",
            ...defined({ color: readToken(styles, "--accent") }),
          },
        ])
      }

      chart.timeScale().fitContent()

      if (typeof ResizeObserver !== "undefined") {
        observer = new ResizeObserver(entries => {
          if (!chart || !entries.length) return
          chart.applyOptions({ width: Math.floor(entries[0].contentRect.width) })
          chart.timeScale().fitContent()
        })
        observer.observe(container)
      }
    }

    mount()

    return () => {
      cancelled = true
      if (observer) observer.disconnect()
      if (chart) chart.remove()
    }
  }, [candles, height, markerTime])

  return <div className="delta-chart" ref={containerRef} style={{ height: height + "px" }} />
}
