/**
 * Interval-over-interval change for a symbol.
 *
 * The rule this module exists to demonstrate: `before` and `after` are TWO
 * SLICES OF ONE CANDLE ARRAY. The series is built once, every indicator is
 * computed once over the WHOLE series, and each window then samples those
 * arrays at its own last index.
 *
 * The tempting shortcut — recomputing RSI over a five-bar slice — is
 * meaningless: a 14-period RSI needs 15 bars, so a five-bar recompute would
 * return null or, worse, a number derived from a different seed window than the
 * one the chart plots.
 */

import { generateCandles } from "./candles.js"
import { getIndicators } from "./indicators.js"
import { countNewsBetween } from "./news.js"

export const DELTA_INTERVALS = ["1m", "5m", "15m", "1h", "daily"]

const MINUTE = 60
const SESSION_SECONDS = 390 * MINUTE

/**
 * Window size in bars, which series to read, and how far back to count news.
 *
 * The news lookback is deliberately WIDER than the price window. A raw
 * one-minute news count is always zero for both sides, which makes the row
 * useless on screen; widening it to a meaningful recency horizon keeps the
 * comparison honest while actually showing movement.
 */
const CONFIG = {
  "1m": { bars: 1, timeframe: "1D", source: "1D intraday", newsLookback: 30 * MINUTE },
  "5m": { bars: 5, timeframe: "1D", source: "1D intraday", newsLookback: 2 * 3600 },
  "15m": { bars: 15, timeframe: "1D", source: "1D intraday", newsLookback: 6 * 3600 },
  "1h": { bars: 60, timeframe: "1D", source: "1D intraday", newsLookback: SESSION_SECONDS },
  daily: { bars: 1, timeframe: "1M", source: "1M daily", newsLookback: 5 * 86400 },
}

const ROW_META = [
  { key: "price", label: "Price", unit: "USD" },
  { key: "volume", label: "Volume", unit: "shares" },
  { key: "rvol", label: "RVOL", unit: "x" },
  { key: "atr", label: "ATR (14)", unit: "USD" },
  { key: "momentum", label: "Momentum", unit: "%" },
  { key: "newsCount", label: "News items", unit: "count" },
  { key: "rsi", label: "RSI (14)", unit: "" },
  { key: "macd", label: "MACD histogram", unit: "" },
  { key: "vwap", label: "VWAP", unit: "USD" },
]

function num(value) {
  return value !== null && Number.isFinite(value) ? value : null
}

/** Mean volume across every non-overlapping window of `bars` length in the series. */
function meanWindowVolume(candles, bars) {
  const windows = Math.floor(candles.length / bars)
  if (windows < 1) return null
  let total = 0
  for (let i = 0; i < windows * bars; i += 1) total += candles[i].volume
  return total / windows
}

function buildRows(before, after) {
  return ROW_META.map(meta => {
    const b = num(before[meta.key])
    const a = num(after[meta.key])

    let delta = null
    let deltaPct = null
    if (b !== null && a !== null) {
      delta = a - b
      // Undefined against a zero base — return null rather than Infinity.
      deltaPct = b === 0 ? null : ((a - b) / Math.abs(b)) * 100
    }

    const direction = delta === null || delta === 0 ? "flat" : delta > 0 ? "up" : "down"

    return {
      key: meta.key,
      label: meta.label,
      unit: meta.unit,
      before: b,
      after: a,
      delta,
      deltaPct: deltaPct !== null && Number.isFinite(deltaPct) ? deltaPct : null,
      direction,
    }
  })
}

const NULL_WINDOW = ROW_META.reduce((acc, m) => {
  acc[m.key] = null
  return acc
}, {})

/**
 * The last bar index available for a given symbol and interval.
 * The /delta screen uses this to bound its playback cursor.
 */
export function getDeltaBounds(symbol, interval) {
  const config = CONFIG[interval] || CONFIG["5m"]
  const candles = generateCandles(symbol, config.timeframe)
  const n = candles.length
  return {
    bars: config.bars,
    length: n,
    // The earliest cursor that still has two full windows behind it.
    minCursor: config.bars * 2 - 1,
    maxCursor: n - 1,
  }
}

/**
 * @param {string} symbol
 * @param {string} interval  one of DELTA_INTERVALS
 * @param {object} [options]
 * @param {number} [options.cursor]  index of the LAST bar of the "after" window.
 *   Defaults to the live edge. The /delta screen walks this forward one bar at a
 *   time so auto-refresh drifts through real candles rather than inventing
 *   numbers — every refreshed value is still read from the same generated series.
 */
export function getDelta(symbol, interval, options) {
  const config = CONFIG[interval] || CONFIG["5m"]
  const resolved = CONFIG[interval] ? interval : "5m"
  const { bars, timeframe, source, newsLookback } = config

  const candles = generateCandles(symbol, timeframe)
  const n = candles.length

  // Not enough history for two full, non-overlapping windows.
  if (n < bars * 2) {
    return {
      symbol,
      interval: resolved,
      windowBars: bars,
      source,
      cursor: null,
      beforeTime: null,
      afterTime: null,
      rows: buildRows(NULL_WINDOW, NULL_WINDOW),
    }
  }

  // Clamp the cursor into the range that has two full windows behind it.
  const requested =
    options && Number.isFinite(options.cursor) ? Math.round(options.cursor) : n - 1
  const cursor = Math.max(bars * 2 - 1, Math.min(n - 1, requested))

  // Indicators computed ONCE over the whole series, then sampled per window.
  const ind = getIndicators(symbol, timeframe)
  const meanVolume = meanWindowVolume(candles, bars)

  function windowAt(endIndex) {
    const startIndex = endIndex - bars + 1
    let volume = 0
    for (let i = startIndex; i <= endIndex; i += 1) volume += candles[i].volume

    const openPrice = candles[startIndex].open
    const closePrice = candles[endIndex].close
    const endTime = candles[endIndex].time

    return {
      price: closePrice,
      volume,
      rvol: meanVolume && meanVolume > 0 ? volume / meanVolume : null,
      atr: ind.atr14[endIndex],
      momentum: openPrice > 0 ? ((closePrice - openPrice) / openPrice) * 100 : null,
      newsCount: countNewsBetween(symbol, endTime - newsLookback, endTime),
      rsi: ind.rsi14[endIndex],
      macd: ind.macd.histogram[endIndex],
      vwap: ind.vwap[endIndex],
    }
  }

  const after = windowAt(cursor)
  const before = windowAt(cursor - bars)

  return {
    symbol,
    interval: resolved,
    windowBars: bars,
    source,
    cursor,
    // The bar timestamps behind each column, so the UI can label them honestly
    // ("Comparing 9:35 AM to 9:36 AM") instead of guessing.
    beforeTime: candles[cursor - bars].time,
    afterTime: candles[cursor].time,
    isLive: cursor === n - 1,
    rows: buildRows(before, after),
  }
}
